-- Subly initial schema (Phase 0 domain model).
-- Conventions:
--   * UUID primary keys generated by the application, never by the database.
--   * Money is NUMERIC(19,4) + an ISO-4217 currency column. Never float.
--   * Balances are never stored; they are computed from ledger_entry.
--   * Statuses are TEXT with CHECK constraints mirroring the Java enums.

-- ───────────────────────────── Auth ─────────────────────────────
CREATE TABLE account (
    id          UUID PRIMARY KEY,
    name        TEXT        NOT NULL,
    role        TEXT        NOT NULL CHECK (role IN ('ADMIN', 'DEVELOPER', 'READONLY')),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE api_key (
    id            UUID PRIMARY KEY,
    account_id    UUID        NOT NULL REFERENCES account (id),
    sha256_hash   CHAR(64)    NOT NULL UNIQUE,
    prefix        TEXT        NOT NULL,             -- first chars shown in UIs, e.g. "sb_live_ab12"
    revoked_at    TIMESTAMPTZ,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ─────────────────────────── Catalog ────────────────────────────
CREATE TABLE product (
    id          UUID PRIMARY KEY,
    name        TEXT        NOT NULL,
    active      BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE plan (
    id          UUID PRIMARY KEY,
    product_id  UUID        NOT NULL REFERENCES product (id),
    name        TEXT        NOT NULL,
    interval    TEXT        NOT NULL CHECK (interval IN ('MONTH', 'YEAR')),
    trial_days  INT         NOT NULL DEFAULT 0 CHECK (trial_days >= 0),
    active      BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE price (
    id           UUID PRIMARY KEY,
    plan_id      UUID          NOT NULL REFERENCES plan (id),
    model        TEXT          NOT NULL CHECK (model IN ('FLAT', 'PER_SEAT', 'TIERED')),
    unit_amount  NUMERIC(19,4),                     -- NULL for TIERED (see price_tier)
    currency     CHAR(3)       NOT NULL,
    created_at   TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CHECK (model = 'TIERED' OR unit_amount IS NOT NULL)
);

CREATE TABLE price_tier (
    id           UUID PRIMARY KEY,
    price_id     UUID          NOT NULL REFERENCES price (id),
    up_to        INT,                               -- NULL = infinity (last tier)
    unit_amount  NUMERIC(19,4) NOT NULL
);

-- ─────────────────────── Customers & subs ───────────────────────
CREATE TABLE customer (
    id          UUID PRIMARY KEY,
    email       TEXT        NOT NULL UNIQUE,
    name        TEXT        NOT NULL,
    currency    CHAR(3)     NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE payment_method (
    id           UUID PRIMARY KEY,
    customer_id  UUID        NOT NULL REFERENCES customer (id),
    mock_token   TEXT        NOT NULL,              -- mock provider token, never real card data
    is_default   BOOLEAN     NOT NULL DEFAULT FALSE,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX ux_payment_method_default ON payment_method (customer_id) WHERE is_default;

CREATE TABLE subscription (
    id                    UUID PRIMARY KEY,
    customer_id           UUID        NOT NULL REFERENCES customer (id),
    status                TEXT        NOT NULL CHECK (status IN ('TRIALING', 'ACTIVE', 'PAST_DUE', 'CANCELED')),
    current_period_start  TIMESTAMPTZ NOT NULL,
    current_period_end    TIMESTAMPTZ NOT NULL,
    trial_end             TIMESTAMPTZ,
    cancel_at_period_end  BOOLEAN     NOT NULL DEFAULT FALSE,
    canceled_at           TIMESTAMPTZ,
    version               BIGINT      NOT NULL DEFAULT 0,   -- optimistic locking
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- The billing scheduler's main query: "what is due?"
CREATE INDEX ix_subscription_due ON subscription (current_period_end) WHERE status IN ('TRIALING', 'ACTIVE', 'PAST_DUE');

CREATE TABLE subscription_item (
    id               UUID PRIMARY KEY,
    subscription_id  UUID NOT NULL REFERENCES subscription (id),
    price_id         UUID NOT NULL REFERENCES price (id),
    quantity         INT  NOT NULL DEFAULT 1 CHECK (quantity > 0)
);

CREATE TABLE usage_record (
    id                    UUID PRIMARY KEY,
    subscription_item_id  UUID        NOT NULL REFERENCES subscription_item (id),
    quantity              INT         NOT NULL CHECK (quantity >= 0),
    recorded_at           TIMESTAMPTZ NOT NULL
);

-- ─────────────────────────── Invoicing ──────────────────────────
CREATE SEQUENCE invoice_number_seq START 1000;   -- gap-free numbering is a known trade-off, see ADR

CREATE TABLE invoice (
    id               UUID PRIMARY KEY,
    number           TEXT          UNIQUE,          -- assigned on finalisation (DRAFT -> OPEN)
    customer_id      UUID          NOT NULL REFERENCES customer (id),
    subscription_id  UUID          REFERENCES subscription (id),
    status           TEXT          NOT NULL CHECK (status IN ('DRAFT', 'OPEN', 'PAID', 'VOID', 'UNCOLLECTIBLE')),
    currency         CHAR(3)       NOT NULL,
    total            NUMERIC(19,4) NOT NULL DEFAULT 0,
    period_start     TIMESTAMPTZ,
    period_end       TIMESTAMPTZ,
    due_at           TIMESTAMPTZ,
    finalized_at     TIMESTAMPTZ,
    paid_at          TIMESTAMPTZ,
    version          BIGINT        NOT NULL DEFAULT 0,
    created_at       TIMESTAMPTZ   NOT NULL DEFAULT now()
);
-- One invoice per subscription per period: makes the billing run idempotent.
CREATE UNIQUE INDEX ux_invoice_sub_period ON invoice (subscription_id, period_start) WHERE subscription_id IS NOT NULL;

CREATE TABLE invoice_line (
    id                    UUID PRIMARY KEY,
    invoice_id            UUID          NOT NULL REFERENCES invoice (id),
    subscription_item_id  UUID          REFERENCES subscription_item (id),
    description           TEXT          NOT NULL,
    quantity              INT           NOT NULL DEFAULT 1,
    amount                NUMERIC(19,4) NOT NULL,      -- negative for proration credits
    proration             BOOLEAN       NOT NULL DEFAULT FALSE
);

-- ─────────────────────────── Payments ───────────────────────────
CREATE TABLE payment (
    id                 UUID PRIMARY KEY,
    invoice_id         UUID          NOT NULL REFERENCES invoice (id),
    payment_method_id  UUID          REFERENCES payment_method (id),
    status             TEXT          NOT NULL CHECK (status IN ('PENDING', 'SUCCEEDED', 'FAILED')),
    amount             NUMERIC(19,4) NOT NULL CHECK (amount > 0),
    currency           CHAR(3)       NOT NULL,
    attempt_no         INT           NOT NULL DEFAULT 1,
    failure_reason     TEXT,
    idempotency_key    TEXT          NOT NULL UNIQUE,
    created_at         TIMESTAMPTZ   NOT NULL DEFAULT now()
);

CREATE TABLE refund (
    id          UUID PRIMARY KEY,
    payment_id  UUID          NOT NULL REFERENCES payment (id),
    amount      NUMERIC(19,4) NOT NULL CHECK (amount > 0),
    reason      TEXT,
    created_at  TIMESTAMPTZ   NOT NULL DEFAULT now()
);

CREATE TABLE credit_note (
    id          UUID PRIMARY KEY,
    invoice_id  UUID          NOT NULL REFERENCES invoice (id),
    amount      NUMERIC(19,4) NOT NULL CHECK (amount > 0),
    reason      TEXT          NOT NULL,
    created_at  TIMESTAMPTZ   NOT NULL DEFAULT now()
);

-- Accounts-receivable ledger. Append-only: never UPDATE or DELETE rows.
CREATE TABLE ledger_entry (
    id           UUID PRIMARY KEY,
    customer_id  UUID          NOT NULL REFERENCES customer (id),
    source       TEXT          NOT NULL CHECK (source IN ('INVOICE', 'PAYMENT', 'CREDIT_NOTE', 'REFUND')),
    source_id    UUID          NOT NULL,
    direction    TEXT          NOT NULL CHECK (direction IN ('DEBIT', 'CREDIT')),
    amount       NUMERIC(19,4) NOT NULL CHECK (amount > 0),
    currency     CHAR(3)       NOT NULL,
    created_at   TIMESTAMPTZ   NOT NULL DEFAULT now()
);
CREATE INDEX ix_ledger_customer ON ledger_entry (customer_id);

-- ────────────────────── Events & webhooks ───────────────────────
CREATE TABLE outbox_event (
    id            UUID PRIMARY KEY,
    event_type    TEXT        NOT NULL,             -- e.g. invoice.paid
    aggregate_id  UUID        NOT NULL,
    payload       JSONB       NOT NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    published_at  TIMESTAMPTZ
);
CREATE INDEX ix_outbox_unpublished ON outbox_event (created_at) WHERE published_at IS NULL;

CREATE TABLE webhook_endpoint (
    id           UUID PRIMARY KEY,
    url          TEXT        NOT NULL,
    secret       TEXT        NOT NULL,              -- HMAC signing secret; move to encrypted storage later
    enabled      BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE webhook_delivery (
    id                UUID PRIMARY KEY,
    outbox_event_id   UUID        NOT NULL REFERENCES outbox_event (id),
    endpoint_id       UUID        NOT NULL REFERENCES webhook_endpoint (id),
    status            TEXT        NOT NULL CHECK (status IN ('PENDING', 'DELIVERED', 'FAILED', 'DEAD')),
    attempts          INT         NOT NULL DEFAULT 0,
    last_status_code  INT,
    next_attempt_at   TIMESTAMPTZ,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (outbox_event_id, endpoint_id)
);
